INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(1490699, 196672, 37719, '<td valign="top">I wish this had different lighting.  It looks harsh being so bright - almost washed out in places.</td>', 'I wish this had different lighting.  It looks harsh being so bright - almost washed out in places.', '2005-06-29 10:14:29.000000', NULL, 1),
(1490705, 197534, 37719, '<td valign="top">Interesting shot.</td>', 'Interesting shot.', '2005-06-29 10:15:41.000000', NULL, 1),
(1490706, 195005, 37719, '<td valign="top">I think this would be stronger if it was clearer.  The subject looks soft/fuzzy while the wall looks crisp.</td>', 'I think this would be stronger if it was clearer.  The subject looks soft/fuzzy while the wall looks crisp.', '2005-06-29 10:16:32.000000', NULL, 1),
(1490707, 197407, 27786, '<td valign="top">Þjóðlegt! :-)</td>', 'Þjóðlegt! :-)', '2005-06-29 10:16:36.000000', NULL, 1),
(1490710, 194150, 27786, '<td valign="top">It''s almost too dark.</td>', 'It''s almost too dark.', '2005-06-29 10:17:05.000000', NULL, 1),
(1490713, 195708, 37719, '<td valign="top">Not a very clear shot - subject looks fuzzy.  Although the challenge was pretty much wide open for possibilities, I fail to see how this relates to the criteria.</td>', 'Not a very clear shot - subject looks fuzzy.  Although the challenge was pretty much wide open for possibilities, I fail to see how this relates to the criteria.', '2005-06-29 10:17:29.000000', NULL, 1),
(1490715, 197431, 37719, '<td valign="top">I understand the concept, but the inclusion of the bible text just turns me off completely.</td>', 'I understand the concept, but the inclusion of the bible text just turns me off completely.', '2005-06-29 10:18:18.000000', NULL, 1),
(1490716, 196106, 37719, '<td valign="top">Interesting picture.  I like the black and white.  But unless you know the building, the title makes no sense.  Nothing in the shot indicates decline or British.</td>', 'Interesting picture.  I like the black and white.  But unless you know the building, the title makes no sense.  Nothing in the shot indicates decline or British.', '2005-06-29 10:19:53.000000', NULL, 1),
(1490718, 197438, 27786, '<td valign="top">Faceless would have been a great title also!</td>', 'Faceless would have been a great title also!', '2005-06-29 10:21:05.000000', NULL, 1),
(1490719, 197275, 37719, '<td valign="top">I like this photo but I think it falls a little short.  Your subject is too far away to be a main focal point.  I am drawn to the contrast between the beach and the water and the ruin just blends into a distant horizon.</td>', 'I like this photo but I think it falls a little short.  Your subject is too far away to be a main focal point.  I am drawn to the contrast between the beach and the water and the ruin just blends into a distant horizon.', '2005-06-29 10:21:24.000000', NULL, 1),
(1490721, 194213, 38930, '<td valign="top">That certainly has out-used its usefullness!</td>', 'That certainly has out-used its usefullness!', '2005-06-29 10:22:09.000000', NULL, 1),
(1490724, 197160, 37719, '<td valign="top">I would have liked this much better as a black and white.  it could have been cropped to remove more of the grass in the front.  The items behind the door are a big distraction - immediately draws my eye takingt away from the subject - the shack itself.</td>', 'I would have liked this much better as a black and white.  it could have been cropped to remove more of the grass in the front.  The items behind the door are a big distraction - immediately draws my eye takingt away from the subject - the shack itself.', '2005-06-29 10:22:44.000000', NULL, 1),
(1490726, 197641, 37719, '<td valign="top">My only comment would be it would have been stronger if the funnel wasn''t in the shot.  It just makes it look sloppy somehow.</td>', 'My only comment would be it would have been stronger if the funnel wasn''t in the shot.  It just makes it look sloppy somehow.', '2005-06-29 10:23:30.000000', NULL, 1),
(1490728, 196639, 36429, '<td valign="top">Not fond of the composition, but I just love the colours and overall feel. Almost like those old print ads.  8</td>', 'Not fond of the composition, but I just love the colours and overall feel. Almost like those old print ads.  8', '2005-06-29 10:23:38.000000', NULL, 1),
