(1490732, 197642, 37719, '<td valign="top">would have been much better without the paper and typed words on the paper.</td>', 'would have been much better without the paper and typed words on the paper.', '2005-06-29 10:25:36.000000', NULL, 1),
(1490734, 194224, 36429, '<td valign="top">I like the texture here. Interesting.</td>', 'I like the texture here. Interesting.', '2005-06-29 10:26:21.000000', NULL, 1),
