(1498872, 197080, 30791, '<td valign="top">cool picture marbo</td>', 'cool picture marbo', '2005-07-02 01:51:36.000000', NULL, 1),
(1498873, 196226, 30791, '<td valign="top">grungy</td>', 'grungy', '2005-07-02 01:53:13.000000', NULL, 1),
(1498875, 196448, 1993, '<td valign="top">magical.  The great height of sky against the highlighted teepees is wonderful.  A little fuzzy, but still a very strong composition.  I imagine it as a fantastic painting  circa Remington.  Nice job!</td>', 'magical.  The great height of sky against the highlighted teepees is wonderful.  A little fuzzy, but still a very strong composition.  I imagine it as a fantastic painting  circa Remington.  Nice job!', '2005-07-02 01:53:27.000000', NULL, 1),
