(1501758, 196823, 39531, '<td valign="top">Nice shot ... might have looked more appealing with a longer exposure to give the water a chance to be more flowing. Also maybe crop just a bit more of the right that isn''t really adding to the shot.</td>', 'Nice shot ... might have looked more appealing with a longer exposure to give the water a chance to be more flowing. Also maybe crop just a bit more of the right that isn''t really adding to the shot.', '2005-07-03 13:38:55.000000', NULL, 1),
(1501759, 195267, 39531, '<td valign="top">Technically very well done.</td>', 'Technically very well done.', '2005-07-03 13:39:20.000000', NULL, 1),
(1501761, 197055, 39531, '<td valign="top">Nice shot ...</td>', 'Nice shot ...', '2005-07-03 13:39:33.000000', NULL, 1),
(1501762, 197500, 39531, '<td valign="top">I think cropping and brighting could make this a bit more dramatic ... this looks very much like a snapshot.</td>', 'I think cropping and brighting could make this a bit more dramatic ... this looks very much like a snapshot.', '2005-07-03 13:40:21.000000', NULL, 1),
(1501764, 197434, 39531, '<td valign="top">Lighting is too washed out. Need to slightly underexpose to bring out the saturation and darken the subject.</td>', 'Lighting is too washed out. Need to slightly underexpose to bring out the saturation and darken the subject.', '2005-07-03 13:41:02.000000', NULL, 1),
(1501765, 197257, 39531, '<td valign="top">Nice shout though I found it a bit too dark.</td>', 'Nice shout though I found it a bit too dark.', '2005-07-03 13:41:23.000000', NULL, 1),
(1501766, 197567, 39531, '<td valign="top">Shot is too bright , sky is washed out and colors are too flat.</td>', 'Shot is too bright , sky is washed out and colors are too flat.', '2005-07-03 13:41:50.000000', NULL, 1),
