(1501796, 197559, 39531, '<td valign="top">excellent shot</td>', 'excellent shot', '2005-07-03 13:53:39.000000', NULL, 1),
(1501798, 195730, 39531, '<td valign="top">good use of dramatic lighting ...</td>', 'good use of dramatic lighting ...', '2005-07-03 13:53:59.000000', NULL, 1),
(1501800, 196616, 38725, '<td valign="top">Nice abstract shot, shame it isn''t larger.</td>', 'Nice abstract shot, shame it isn''t larger.', '2005-07-03 13:55:08.000000', NULL, 1),
(1501801, 196930, 39531, '<td valign="top">sky is washed out and makes the colors bland. Slightly underexpose or change the angle of the shot to take out the high contrast.</td>', 'sky is washed out and makes the colors bland. Slightly underexpose or change the angle of the shot to take out the high contrast.', '2005-07-03 13:55:24.000000', NULL, 1),
