(1501804, 197302, 39531, '<td valign="top">very well shot and good use of lighting.</td>', 'very well shot and good use of lighting.', '2005-07-03 13:56:05.000000', NULL, 1),
(1501806, 197496, 39531, '<td valign="top">interesting use of lighting ... I find the beige sky a bit detracting but, a nice shot.</td>', 'interesting use of lighting ... I find the beige sky a bit detracting but, a nice shot.', '2005-07-03 13:56:48.000000', NULL, 1),
(1501807, 196136, 33947, '<td valign="top">I like the mood of this shot. Captures the essence of the theme well. Works nicely in sepia. One of my top favs. 10</td>', 'I like the mood of this shot. Captures the essence of the theme well. Works nicely in sepia. One of my top favs. 10', '2005-07-03 13:57:10.000000', NULL, 1),
(1501809, 196257, 39531, '<td valign="top">Too much empty space ... this empty space creates excessive contrast which prevents your subject from being more dramatically lit and colored. I think this is an attempt to fit the rule of thirds in where it doesn''t suit you.</td>', 'Too much empty space ... this empty space creates excessive contrast which prevents your subject from being more dramatically lit and colored. I think this is an attempt to fit the rule of thirds in where it doesn''t suit you.', '2005-07-03 13:57:54.000000', NULL, 1),
