(1505767, 194859, 6172, '<td valign="top">How is this obsolete?</td>', 'How is this obsolete?', '2005-07-04 17:05:57.000000', NULL, 1),
(1505770, 195201, 40192, '<td valign="top">good idea, not very impressive though. 4</td>', 'good idea, not very impressive though. 4', '2005-07-04 17:07:19.000000', NULL, 1),
(1505773, 195708, 40192, '<td valign="top">doesn''t meet the challenge</td>', 'doesn''t meet the challenge', '2005-07-04 17:09:51.000000', NULL, 1),
(1505777, 196934, 6172, '<td valign="top">If your subject weren''t right in the middle of the photo I would''ve scored it higher.</td>', 'If your subject weren''t right in the middle of the photo I would''ve scored it higher.', '2005-07-04 17:12:07.000000', NULL, 1),
(1505791, 195769, 6172, '<td valign="top">I find the sidewalk at the bottom distracting.  A closer crop would''ve worked better I think.  Good idea, though.</td>', 'I find the sidewalk at the bottom distracting.  A closer crop would''ve worked better I think.  Good idea, though.', '2005-07-04 17:16:29.000000', NULL, 1),
(1505795, 197255, 6172, '<td valign="top">overexposed</td>', 'overexposed', '2005-07-04 17:17:13.000000', NULL, 1),
