(1505808, 197508, 6172, '<td valign="top">I like the wide angle effect here, but it could stand to be sharper</td>', 'I like the wide angle effect here, but it could stand to be sharper', '2005-07-04 17:20:35.000000', NULL, 1),
(1505811, 197539, 40192, '<td valign="top">The greatest idea regarding a typewriter that i have seen so far!  7</td>', 'The greatest idea regarding a typewriter that i have seen so far!  7', '2005-07-04 17:21:21.000000', NULL, 1),
(1505813, 197187, 40192, '<td valign="top">Amazing lights, a little distorted though. 6</td>', 'Amazing lights, a little distorted though. 6', '2005-07-04 17:22:25.000000', NULL, 1),
